1: /**
2:  * JSON-LD Structured Data Helpers
3:  * Based on nextjs-seo-skill best practices
4:  */
5: 
6: /**
7:  * Safe JSON-LD serialization (Session 71).
8:  *
9:  * `JSON.stringify` alone does NOT escape `<`/`>`/`&`, so product data
10:  * containing e.g. `</script><script>alert(1)</script>` would break out of the
11:  * `<script type="application/ld+json">` element (the HTML parser closes the
12:  * script early → markup injection / broken structured data). Escaping the
13:  * five dangerous sequences keeps the JSON valid (the escapes decode to the
14:  * original characters when parsed) while making script-tag breakout
15:  * impossible. Do NOT trust editor/API content merely because it came from the
16:  * admin UI.
17:  */
18: export function serializeJsonLd(data: Record<string, unknown>): string {
19:   return JSON.stringify(data)
20:     .replace(/</g, "\\u003c")
21:     .replace(/>/g, "\\u003e")
22:     .replace(/&/g, "\\u0026")
23:     .replace(/\u2028/g, "\\u2028")
24:     .replace(/\u2029/g, "\\u2029");
25: }
