141: /**
142:  * BreadcrumbList Schema (Session 72).
143:  *
144:  * Google's current guidance: `position` (1-based, strictly sequential) and
145:  * `name` are required on every ListItem; `item` (the absolute URL) is
146:  * required for intermediate elements but OPTIONAL on the final (current
147:  * page) element — search engines infer the current page's URL from the
148:  * crawled page itself. The final breadcrumb (the product) therefore carries
149:  * no `item` and is never a self-link in the visible UI.
150:  */
151: export function breadcrumbSchema(items: Array<{ name: string; url?: string }>) {
152:   return {
153:     "@context": "https://schema.org",
154:     "@type": "BreadcrumbList",
155:     itemListElement: items.map((item, index) => ({
156:       "@type": "ListItem",
157:       position: index + 1,
158:       name: item.name,
159:       ...(item.url ? { item: item.url } : {}),
160:     })),
161:   };
162: }
