167: export function productSchema({
168:   name,
169:   description,
170:   image,
171:   sku,
172:   brand,
173:   url,
174:   offers,
175:   aggregateRating,
176: }: {
177:   name: string;
178:   description: string;
179:   image?: string[];
180:   sku?: string;
181:   brand?: string;
182:   /** Canonical product URL (Session 70 — drives structured data + canonical). */
183:   url?: string;
184:   offers: {
185:     price: number;
186:     priceCurrency: string;
187:     availability: "InStock" | "OutOfStock" | "PreOrder";
188:     url?: string;
189:     /** Active-discount end (Session 77) — ISO date; ONLY when the discount is live AND finite. */
190:     priceValidUntil?: string;
191:   };
192:   aggregateRating?: {
193:     ratingValue: number;
194:     reviewCount: number;
195:   };
196: }) {
197:   const schema: Record<string, unknown> = {
198:     "@context": "https://schema.org",
199:     "@type": "Product",
200:     name,
201:     description,
202:     ...(image && image.length > 0 && { image }),
203:     ...(sku && { sku }),
204:     ...(brand && { brand: { "@type": "Brand", name: brand } }),
205:     ...(url && { url }),
206:     offers: {
207:       "@type": "Offer",
208:       price: offers.price,
209:       priceCurrency: offers.priceCurrency,
210:       availability: `https://schema.org/${offers.availability}`,
211:       ...(offers.url && { url: offers.url }),
212:       ...(offers.priceValidUntil && {
213:         priceValidUntil: offers.priceValidUntil,
214:       }),
215:     },
216:   };
217: 
218:   if (aggregateRating) {
219:     schema.aggregateRating = {
220:       "@type": "AggregateRating",
221:       ratingValue: aggregateRating.ratingValue,
222:       reviewCount: aggregateRating.reviewCount,
223:     };
224:   }
225: 
226:   return schema;
227: }
