229: /**
230:  * ItemList Schema (Session 75) — category-page first-page products.
231:  *
232:  * Only FACTUAL fields that already exist on the product are emitted:
233:  * `position` (1-based, sequential), `name` and `url`. No price, rating,
234:  * review count or availability is ever fabricated for the structured data.
235:  * ItemList here describes the visible list (the products actually rendered
236:  * on the page) — it is not a product-collection shortcut for the Product
237:  * schema on the detail pages.
238:  */
239: export function itemListSchema(items: Array<{ name: string; url: string }>) {
240:   return {
241:     "@context": "https://schema.org",
242:     "@type": "ItemList",
243:     itemListElement: items.map((item, index) => ({
244:       "@type": "ListItem",
245:       position: index + 1,
246:       name: item.name,
247:       url: item.url,
248:     })),
249:   };
250: }
