253:  * FAQPage Schema
254:  */
255: export function faqSchema(questions: Array<{ question: string; answer: string }>) {
256:   return {
257:     "@context": "https://schema.org",
258:     "@type": "FAQPage",
259:     mainEntity: questions.map((q) => ({
260:       "@type": "Question",
261:       name: q.question,
262:       acceptedAnswer: {
263:         "@type": "Answer",
264:         text: q.answer,
265:       },
266:     })),
267:   };
