270: /**
271:  * LocalBusiness Schema
272:  */
273: export function localBusinessSchema({
274:   name,
275:   description,
276:   url,
277:   telephone,
278:   address,
279:   openingHours,
280: }: {
281:   name: string;
282:   description: string;
283:   url: string;
284:   telephone?: string;
285:   address?: {
286:     streetAddress: string;
287:     addressLocality: string;
288:     addressRegion: string;
289:     postalCode: string;
290:     addressCountry: string;
291:   };
292:   openingHours?: string[];
293: }) {
294:   const schema: Record<string, unknown> = {
295:     "@context": "https://schema.org",
296:     "@type": "LocalBusiness",
297:     name,
298:     description,
299:     url,
300:   };
301: 
302:   if (telephone) schema.telephone = telephone;
303: 
304:   if (address) {
305:     schema.address = {
306:       "@type": "PostalAddress",
307:       ...address,
308:     };
309:   }
310: 
311:   if (openingHours) {
312:     schema.openingHoursSpecification = openingHours.map((hours) => ({
313:       "@type": "OpeningHoursSpecification",
314:       ...parseHours(hours),
315:     }));
316:   }
317: 
318:   return schema;
319: }
320: 
321: function parseHours(hours: string) {
322:   const [days, timeRange] = hours.split(" ");
323:   const [opens, closes] = timeRange.split("-");
324:   return {
325:     dayOfWeek: days.split(",").map((d) => `https://schema.org/${d.trim()}`),
326:     opens,
327:     closes,
328:   };
329: }

