136:   const docs = await Order.aggregate([
137:     ...stages,
138:     {
139:       $project: {
140:         orderId: "$_id",
141:         createdAt: 1,
142:         orderStatus: "$status",
143:         paymentStatus: "$payment.status",
144:         productId: "$items.product",
145:         sku: { $ifNull: ["$items.sku", ""] },
146:         name: "$items.name",
147:         variantId: { $ifNull: ["$items.variantId", null] },
148:         variantLabel: { $ifNull: ["$items.variantLabel", ""] },
149:         quantity: "$items.quantity",
150:         unitPrice: "$items.price",
151:         originalPrice: { $ifNull: ["$items.originalPrice", "$items.price"] },
152:         discountAmount: { $ifNull: ["$items.discountAmount", 0] },
153:         supplierPrice: "$items.supplierPrice",
154:         fifoUnitCost: { $ifNull: ["$items.fifoUnitCost", null] },
155:         lineNet: { $multiply: ["$items.price", "$items.quantity"] },
156:         subtotalAmount: { $ifNull: ["$subtotalAmount", 0] },
157:         couponAmount: { $ifNull: ["$discount.amount", 0] },
