483: /** Active FIFO cost layers — allows reconciling inventory value (Σ remaining × unitCost). */
484: export async function getCostLayersReport(filters: ReportFilters) {
485:   const query: Record<string, unknown> = {};
486:   if (filters.productId) query._id = new ObjectId(filters.productId);
487:   if (filters.q) query.name = new RegExp(filters.q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i");
488: 
489:   const products = await Product.find(query)
490:     .select(
491:       "name sku hasVariants costLayers variants.label variants.name variants.sku variants.costLayers"
492:     )
493:     .lean();
494: 
495:   const rows: AccountingLayerRow[] = [];
496:   for (const p of products) {
497:     if (p.hasVariants && Array.isArray(p.variants) && p.variants.length > 0) {
498:       for (const v of p.variants as Array<{
499:         _id?: unknown;
500:         label?: string;
501:         name?: string;
502:         sku?: string;
503:         costLayers?: InventoryCostLayerView[];
504:       }>) {
505:         for (const layer of v.costLayers ?? []) {
506:           if (!layer || Number(layer.remaining) <= 0) continue;
507:           rows.push({
508:             productId: String(p._id),
509:             name: p.name,
510:             sku: v.sku || p.sku || "",
511:             variantId: v._id ? String(v._id) : "",
512:             variantLabel: v.label || v.name || "",
513:             source: String(layer.source || ""),
514:             sourceLabel: LAYER_SOURCE_LABELS[String(layer.source || "")] || String(layer.source || ""),
515:             ref: String(layer.ref || ""),
516:             acquiredAt: layer.acquiredAt
517:               ? new Date(layer.acquiredAt).toISOString()
518:               : "",
519:             originalQty: Number(layer.qty || 0),
520:             remaining: Number(layer.remaining || 0),
521:             unitCost: roundToman(layer.unitCost || 0),
522:             remainingValue: roundToman(Number(layer.remaining || 0) * Number(layer.unitCost || 0)),
523:           });
524:         }
525:       }
526:     } else {
527:       for (const layer of (p.costLayers ?? []) as InventoryCostLayerView[]) {
528:         if (!layer || Number(layer.remaining) <= 0) continue;
529:         rows.push({
530:           productId: String(p._id),
531:           name: p.name,
532:           sku: p.sku || "",
533:           variantId: "",
534:           variantLabel: "",
535:           source: String(layer.source || ""),
536:           sourceLabel: LAYER_SOURCE_LABELS[String(layer.source || "")] || String(layer.source || ""),
537:           ref: String(layer.ref || ""),
538:           acquiredAt: layer.acquiredAt
539:             ? new Date(layer.acquiredAt).toISOString()
540:             : "",
541:           originalQty: Number(layer.qty || 0),
542:           remaining: Number(layer.remaining || 0),
543:           unitCost: roundToman(layer.unitCost || 0),
544:           remainingValue: roundToman(Number(layer.remaining || 0) * Number(layer.unitCost || 0)),
545:         });
546:       }
547:     }
548:   }
549: 
550:   const totals: Record<string, number> = {
551:     remaining: rows.reduce((a, r) => a + r.remaining, 0),
552:     remainingValue: rows.reduce((a, r) => a + r.remainingValue, 0),
553:   };
554: 
555:   const fullCount = rows.length;
556:   const bounded = rows.slice(0, EXPORT_MAX_ROWS);
557:   const start = (filters.page - 1) * filters.limit;
558:   return {
559:     report: "layers",
560:     filters,
561:     rows: bounded.slice(start, start + filters.limit),
562:     total: fullCount,
563:     totals,
564:     page: filters.page,
