574: 
575: export interface AccountingCogsRow {
576:   orderId: string;
577:   orderNo: string;
578:   createdAt: string;
579:   productId: string;
580:   name: string;
581:   sku: string;
582:   variantId: string;
583:   variantLabel: string;
584:   quantity: number;
585:   fifoUnitCost: number | null;
586:   cogs: number;
587:   cogsSource: "fifo" | "snapshot";
588:   cogsSourceLabel: string;
589:   sourceRef: string;
590: }
