592: /**
593:  * COGS sheet — one row per sold line with its authoritative cost source,
594:  * plus negative REFUND REVERSAL rows for refunds issued in the window
595:  * (event-based ledger: a sale line belongs to its sale window, its reversal
596:  * to the refund window). Reversal rows keep Σ sheet rows = P&L net COGS in
597:  * every window, and their cost is the same immutable OrderItem snapshot
598:  * (fifoUnitCost ?? supplierPrice) as the original sale line.
599:  */
600: export async function getCogsReport(filters: ReportFilters) {
601:   const items = await getOrderItemsReport(filters);
602:   const saleRows: AccountingCogsRow[] = items.rows.map((r) => ({
603:     orderId: r.orderId,
604:     orderNo: r.orderNo,
605:     createdAt: r.createdAt,
606:     productId: r.productId,
607:     name: r.name,
608:     sku: r.sku,
609:     variantId: r.variantId,
610:     variantLabel: r.variantLabel,
611:     quantity: r.quantity,
612:     fifoUnitCost: r.fifoUnitCost,
613:     cogs: r.cogs,
614:     cogsSource: r.cogsSource,
615:     cogsSourceLabel: r.cogsSourceLabel,
616:     sourceRef: `sale-${r.orderId}-${r.productId}${r.variantId ? "-" + r.variantId : ""}`,
617:   }));
618: 
619:   // NOTE: after $unwind the line fields are projected flat (post-unwind
620:   // `items` is a single object, not an array).
621:   const refundLines = await Order.aggregate<{
622:     _id: mongoose.Types.ObjectId;
623:     refundedAt: Date | null;
624:     productId: mongoose.Types.ObjectId;
625:     name?: string;
626:     sku?: string;
627:     variantId?: mongoose.Types.ObjectId | null;
628:     variantLabel?: string;
629:     quantity?: number;
630:     fifoUnitCost?: number | null;
631:     supplierPrice?: number | null;
632:   }>([
633:     { $match: buildRefundMatch(filters) as unknown as mongoose.PipelineStage.Match },
634:     { $unwind: "$items" },
635:     {
636:       $project: {
637:         refundedAt: "$refund.refundedAt",
638:         productId: "$items.product",
639:         name: "$items.name",
640:         sku: "$items.sku",
641:         variantId: "$items.variantId",
642:         variantLabel: "$items.variantLabel",
643:         quantity: "$items.quantity",
644:         fifoUnitCost: "$items.fifoUnitCost",
645:         supplierPrice: "$items.supplierPrice",
646:       },
647:     },
648:     { $sort: { refundedAt: -1 } },
649:   ]);
650: 
651:   const reversalRows: AccountingCogsRow[] = refundLines.map((line) => {
652:     const qty = Number(line.quantity ?? 0);
653:     const unitCost =
654:       typeof line.fifoUnitCost === "number" && Number.isFinite(line.fifoUnitCost)
655:         ? Number(line.fifoUnitCost)
656:         : Number(line.supplierPrice ?? 0);
657:     const source = cogsSource(line.fifoUnitCost);
658:     const orderId = String(line._id);
659:     const productId = String(line.productId);
660:     const variantId = line.variantId ? String(line.variantId) : "";
661:     return {
662:       orderId,
663:       orderNo: orderId.slice(-8),
664:       createdAt: line.refundedAt
665:         ? new Date(line.refundedAt).toISOString()
666:         : "",
667:       productId,
668:       name: line.name || "نامشخص",
669:       sku: line.sku || "",
670:       variantId,
671:       variantLabel: line.variantLabel || "",
672:       quantity: -qty,
673:       fifoUnitCost:
674:         typeof line.fifoUnitCost === "number" && Number.isFinite(line.fifoUnitCost)
675:           ? Number(line.fifoUnitCost)
676:           : null,
677:       cogs: -roundToman(unitCost * qty),
678:       cogsSource: source,
679:       cogsSourceLabel: COGS_SOURCE_LABELS[source],
680:       sourceRef: `refund-${orderId}-${productId}${variantId ? "-" + variantId : ""}`,
681:     };
682:   });
683: 
684:   const rows: AccountingCogsRow[] = [...saleRows, ...reversalRows];
685:   return {
686:     report: "cogs",
687:     filters,
688:     rows,
689:     total: rows.length,
690:     totals: { cogs: rows.reduce((a, r) => a + r.cogs, 0), quantity: rows.reduce((a, r) => a + r.quantity, 0) },
691:     page: filters.page,
692:     limit: filters.limit,
693:     truncated: items.truncated,
694:     generatedAt: new Date().toISOString(),
695:   };
696: }
