747:       }
748:     | null;
749:   const cutoverDate = config?.cutoverDate
750:     ? new Date(config.cutoverDate).toISOString()
751:     : null;
752:   const inventoryInitialized = config?.inventoryInitialized ?? false;
753:   const valuationBasisLabel = inventoryInitialized
754:     ? "ارزش موجودی بر اساس لایه‌های FIFO"
755:     : "ارزش موجودی بر اساس بهای تمام‌شده فعلی (پیش از انتقال حسابداری)";
756:   const historicalNote = cutoverDate
757:     ? `اطلاعات تاریخی قبل از تاریخ انتقال حسابداری (${cutoverDate.slice(0, 10)}) بر اساس snapshot ثبت‌شده محاسبه شده است.`
758:     : "اطلاعات تاریخی بر اساس snapshot ثبت‌شده محاسبه شده است.";
759: 
760:   const rows: AccountingSummaryRow[] = [
761:     { key: "grossSales", label: "فروش ناخالص", value: summary.grossSales ?? 0, numFmt: "money" },
762:     { key: "discounts", label: "تخفیف‌ها (محصول + کوپن)", value: (summary.productDiscount ?? 0) + (summary.couponDiscount ?? 0), numFmt: "money" },
763:     { key: "netSales", label: "فروش خالص", value: summary.netSales ?? 0, numFmt: "money" },
764:     { key: "cogs", label: "بهای تمام‌شده (COGS)", value: summary.cogs ?? 0, numFmt: "money" },
765:     { key: "grossProfit", label: "سود ناخالص", value: grossProfit, numFmt: "money" },
766:     { key: "grossMargin", label: "حاشیه سود ناخالص", value: summary.grossMargin, numFmt: "percent" },
767:     { key: "operatingExpenses", label: "هزینه‌های عملیاتی", value: operatingExpenses, numFmt: "money" },
768:     { key: "netProfit", label: "سود خالص", value: netProfit, numFmt: "money" },
769:     { key: "inventoryValue", label: "ارزش موجودی", value: inventoryValue, numFmt: "money", note: valuationBasisLabel },
770:     { key: "inventoryUnits", label: "واحدهای موجودی (لایه‌های فعال)", value: inventoryUnits, numFmt: "count" },
771:     { key: "purchases", label: "خریدها (جمع کل)", value: purchaseTotal, numFmt: "money" },
772:     { key: "purchasePaid", label: "پرداخت‌شده برای خریدها", value: purchasePaid, numFmt: "money" },
773:     { key: "purchaseOutstanding", label: "معوق خریدها", value: purchaseOutstanding, numFmt: "money" },
774:     { key: "expensePaid", label: "هزینه‌های پرداخت‌شده", value: expensePaid, numFmt: "money" },
775:     { key: "expenseOutstanding", label: "هزینه‌های در انتظار پرداخت", value: expenseOutstanding, numFmt: "money" },
776:     { key: "refunds", label: "بازپرداخت‌ها", value: summary.refunds ?? 0, numFmt: "money" },
777:     { key: "refundsCogs", label: "بازگشت بهای تمام‌شده", value: summary.refundsCogs ?? 0, numFmt: "money" },
778:   ];
