809: /**
810:  * Assemble the accounting workbook datasets. Reuses the existing report
811:  * services (sales/orders/payments/refunds/coupons/customers/inventory/pnl/
812:  * purchases/expenses) through the caller — the export route passes the JSON
813:  * report envelope pieces it already fetched.
814:  */
815: export async function getAccountingExportData(
816:   filters: ReportFilters,
817:   pieces: {
818:     summary: ReportSummary;
819:     sales: { totals?: Record<string, number> };
820:     pnl: { current: { summary: ReportSummary; rows: Array<{ key?: string; amount?: number | null }> } };
821:     inventory: { totals?: Record<string, number>; rows?: Array<{ currentStock?: number }> };
822:     purchases: { rows?: Array<{ total?: number; amountPaid?: number; amountOutstanding?: number }>; totals?: Record<string, number> };
823:     expenses: { rows?: Array<{ status?: string; amount?: number }> };
824:   }
825: ): Promise<AccountingExportData> {
826:   const [
827:     orderItems,
828:     purchaseItems,
829:     movements,
830:     layers,
831:   ] = await Promise.all([
832:     getOrderItemsReport(filters),
833:     getPurchaseItemsReport(filters),
834:     getInventoryMovementsReport(filters),
835:     getCostLayersReport(filters),
836:   ]);
837:   const cogs = await getCogsReport(filters);
838: 
839:   const operatingExpensesRow = (pieces.pnl.current.rows ?? []).find(
840:     (r) => r.key === "operatingExpenses"
841:   );
842:   const operatingExpenses = Math.max(
843:     0,
844:     Math.abs(typeof operatingExpensesRow?.amount === "number" ? operatingExpensesRow.amount : 0)
845:   );
846: 
847:   const inventoryValue = pieces.inventory.totals?.inventoryValue ?? 0;
848:   const inventoryUnits = (pieces.inventory.rows ?? []).reduce(
849:     (a, r) => a + (r.currentStock ?? 0),
850:     0
851:   );
852: 
853:   const purchaseRows = pieces.purchases.rows ?? [];
854:   const purchaseTotal = purchaseRows.reduce((a, r) => a + (r.total ?? 0), 0);
855:   const purchasePaid = purchaseRows.reduce((a, r) => a + (r.amountPaid ?? 0), 0);
856:   const purchaseOutstanding = purchaseRows.reduce(
857:     (a, r) => a + (r.amountOutstanding ?? 0),
858:     0
859:   );
860: 
861:   const expenseRows = pieces.expenses.rows ?? [];
862:   const expensePaid = expenseRows
863:     .filter((r) => r.status === "paid")
864:     .reduce((a, r) => a + (r.amount ?? 0), 0);
865:   const expenseOutstanding = expenseRows
866:     .filter((r) => r.status === "pending")
867:     .reduce((a, r) => a + (r.amount ?? 0), 0);
868: 
869:   const accounting = await getAccountingSummary(
870:     filters,
871:     pieces.summary,
872:     operatingExpenses,
873:     inventoryValue,
874:     inventoryUnits,
875:     purchaseTotal,
876:     purchasePaid,
877:     purchaseOutstanding,
878:     expensePaid,
879:     expenseOutstanding
880:   );
881: 
882:   return {
883:     report: "accounting",
884:     filters,
885:     summary: pieces.summary,
886:     orderItems,
887:     purchaseItems,
888:     movements,
889:     layers,
890:     cogs,
891:     accounting,
892:     generatedAt: new Date().toISOString(),
893:   };
894: }

